import{G as e,W as t,n,rt as r}from"./chunks/framework.CzKPlK1V.js";var i=JSON.parse(`{"title":"Slider","description":"","frontmatter":{},"headers":[],"relativePath":"03-developer/models/slider.md","filePath":"03-developer/models/slider.md"}`),a={name:`03-developer/models/slider.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="slider" tabindex="-1">Slider <a class="header-anchor" href="#slider" aria-label="Permalink to “Slider”">​</a></h1><p>The <code>Slider</code> model is used to store slide content. It stores the slide&#39;s primary data, image, publication status, and supplementary information, but it is not responsible for determining how the slide is displayed.</p><p>The display of slides is determined by <code>Theme Part</code> and <code>Segment</code>. Therefore, the existence of this model does not imply that there is a dedicated Slider Segment. A slider can be displayed in different ways depending on the selected Theme Part.</p><p>One important feature of this structure is its support for dynamic supplementary information. Theme Parts can add fields such as a title, subtitle, button text, link, or appearance-related information to slide data as needed for their design, without requiring a separate table structure for each type of slider.</p><h2 id="data-structure" tabindex="-1">Data structure <a class="header-anchor" href="#data-structure" aria-label="Permalink to “Data structure”">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Nullable</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>Unique slide ID</td></tr><tr><td><code>body</code></td><td>LONGTEXT</td><td>No</td><td>Main slide content; this field is translatable</td></tr><tr><td><code>image</code></td><td>VARCHAR(255)</td><td>Yes</td><td>Name or ID of the slide image file</td></tr><tr><td><code>tag</code></td><td>VARCHAR(255)</td><td>Yes</td><td>Optional label; it currently has no defined use in the system and could be used for filtering in the future</td></tr><tr><td><code>user_id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>ID of the user who created the slide</td></tr><tr><td><code>status</code></td><td>TINYINT UNSIGNED</td><td>No</td><td>Slide publication status; <code>0</code> for draft and <code>1</code> for published</td></tr><tr><td><code>data</code></td><td>LONGTEXT, JSON</td><td>Yes</td><td>Dynamic supplementary information in JSON format</td></tr><tr><td><code>created_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Slide creation time</td></tr><tr><td><code>updated_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Time of the last slide update</td></tr></tbody></table><h2 id="relationships" tabindex="-1">Relationships <a class="header-anchor" href="#relationships" aria-label="Permalink to “Relationships”">​</a></h2><h3 id="author" tabindex="-1"><code>author()</code> <a class="header-anchor" href="#author" aria-label="Permalink to “author()”">​</a></h3><p>A <code>belongsTo</code> relationship with the <code>User</code> model that returns the user who created the slide.</p><h2 id="image-management" tabindex="-1">Image management <a class="header-anchor" href="#image-management" aria-label="Permalink to “Image management”">​</a></h2><h3 id="imgurl" tabindex="-1"><code>imgUrl()</code> <a class="header-anchor" href="#imgurl" aria-label="Permalink to “imgUrl()”">​</a></h3><p>Returns the URL of the optimized version of the slide image. If no image has been set for the slide, the URL of the site&#39;s default logo is returned.</p><h3 id="imgoriginalurl" tabindex="-1"><code>imgOriginalUrl()</code> <a class="header-anchor" href="#imgoriginalurl" aria-label="Permalink to “imgOriginalUrl()”">​</a></h3><p>Returns the URL of the original slide image. If no image is available, the default logo is used.</p><h2 id="dynamic-supplementary-information-data" tabindex="-1">Dynamic supplementary information (<code>data</code>) <a class="header-anchor" href="#dynamic-supplementary-information-data" aria-label="Permalink to “Dynamic supplementary information (data)”">​</a></h2><p>The <code>data</code> field stores information added to slides as required by Theme Parts. This information is stored as a collection of key-value pairs.</p><p>For example, a Theme Part might add the following information to slides:</p><ul><li>Button text, such as <code>View offer</code></li><li>Button link, such as <code>/</code></li><li>Slide subtitle</li><li>Other values required for display in the theme</li></ul><p>This data structure allows a Theme Part to define the fields it needs without requiring a new column in the <code>sliders</code> table for each field.</p><h3 id="getdatazattribute" tabindex="-1"><code>getDatazAttribute()</code> <a class="header-anchor" href="#getdatazattribute" aria-label="Permalink to “getDatazAttribute()”">​</a></h3><p>Reads the JSON data stored in <code>data</code> and converts it into an array whose keys are the field names and whose values are the stored content.</p><p>For example, data with the following structure:</p><p><code>[{&quot;key&quot;:&quot;index_hero_btn&quot;,&quot;value&quot;:&quot;View offer&quot;},{&quot;key&quot;:&quot;index_hero_link&quot;,&quot;value&quot;:&quot;/&quot;}]</code></p><p>is converted into an array with the keys <code>index_hero_btn</code> and <code>index_hero_link</code>.</p><h3 id="adddata-key-defaultvalue-null" tabindex="-1"><code>addData($key, $defaultValue = null)</code> <a class="header-anchor" href="#adddata-key-defaultvalue-null" aria-label="Permalink to “addData($key, $defaultValue = null)”">​</a></h3><p>Adds a new field, with its default value, to the supplementary data of all existing slides.</p><p>This method is useful when a Theme Part requires a new field and that field also needs to be added to existing slides.</p><h3 id="remdata-key" tabindex="-1"><code>remData($key)</code> <a class="header-anchor" href="#remdata-key" aria-label="Permalink to “remData($key)”">​</a></h3><p>Removes the specified field from the supplementary data of all existing slides.</p><p>This method is used during the removal lifecycle of a Theme Part to clear data that is no longer needed from slides.</p><h2 id="connection-to-theme-part" tabindex="-1">Connection to Theme Part <a class="header-anchor" href="#connection-to-theme-part" aria-label="Permalink to “Connection to Theme Part”">​</a></h2><p>When added, Theme Parts can define the fields they need using <code>Slider::addData()</code>, and remove them when deleted using <code>Slider::remData()</code>.</p><p>For example, the Theme Part for <code>ParallaxSlider</code> creates three fields for button text, link, and subtitle. It also creates a <code>COLOR</code>-type setting in the <code>Setting</code> model so that the slider text color can be configured through the admin panel.</p><p>In this example, the color setting is stored in the <code>settings</code> table, while data specific to each slide is stored in the <code>data</code> field of the <code>sliders</code> table. This separation keeps the Theme Part&#39;s visual settings distinct from individual slide content.</p><h2 id="translating-supplementary-information" tabindex="-1">Translating supplementary information <a class="header-anchor" href="#translating-supplementary-information" aria-label="Permalink to “Translating supplementary information”">​</a></h2><p>The <code>body</code> field is defined as translatable in the model:</p><p><code>public $translatable = [&#39;body&#39;];</code></p><p>However, the dynamic fields inside <code>data</code> do not directly use this mechanism because their structure is determined at runtime according to the Theme Part.</p><p>If one of these fields needs to be translated, the original text is translated in the inline editing section. This approach allows dynamic content to be translated without requiring a separate, fixed structure for each type of slider.</p><h2 id="technical-notes" tabindex="-1">Technical notes <a class="header-anchor" href="#technical-notes" aria-label="Permalink to “Technical notes”">​</a></h2><ul><li><code>Slider</code> is responsible for storing content, not determining how it is displayed; display depends on <code>Theme Part</code> and <code>Segment</code>.</li><li>The <code>tag</code> field currently has no defined use.</li><li><code>data</code> allows the slide content structure to be extended without adding new columns to the table.</li><li><code>addData()</code> and <code>remData()</code> iterate through all existing slides, so their execution cost increases with the number of slides.</li><li>In the current code, <code>$casts</code> is defined as <code>[&#39;dataz&#39;]</code>. Since this array does not map field names to data types and <code>dataz</code> is computed through an Accessor, it is worth checking whether this definition is actually needed or is a leftover from an earlier implementation.</li></ul>`,41)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};